INSERT INTO Papers (paper_id, conference_id, title, abstract, primary_author_id, status, best_paper_candidate, final_decision_date, created_at) VALUES 
(1, 1, 'Optimizing LLMs for Vietnamese Language', NULL, 14, 'ACCEPTED', FALSE, NULL, '2026-01-07 03:47:42.807835'),
(2, 1, 'Secure Smart Contract Design', NULL, 15, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 03:47:42.807835'),
(3, 1, 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks in an encoder-decoder configuration. The best performing models also connect the encoder and decoder through an attention mechanism. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train. Our model achieves 28.4 BLEU on the WMT 2014 English-to-German translation task, improving over the existing best results, including ensembles by over 2 BLEU. On the WMT 2014 English-to-French translation task, our model establishes a new single-model state-of-the-art BLEU score of 41.8 after training for 3.5 days on eight GPUs, a small fraction of the training costs of the best models from the literature. We show that the Transformer generalizes well to other tasks by applying it successfully to English constituency parsing both with large and limited training data.', 15, 'ACCEPTED', TRUE, NULL, '2026-01-07 04:29:04.768495'),
(4, 1, 'Generative Adversarial Nets', 'We propose a new framework for estimating generative models via an adversarial process, in which we simultaneously train two models: a generative model G that captures the data distribution, and a discriminative model D that estimates the probability that a sample came from the training data rather than G. The training procedure for G is to maximize the probability of D making a mistake. This framework corresponds to a minimax two-player game. In the space of arbitrary functions G and D, a unique solution exists, with G recovering the training data distribution and D equal to 1/2 everywhere. In the case where G and D are defined by multilayer perceptrons, the entire system can be trained with backpropagation. There is no need for any Markov chains or unrolled approximate inference networks during either training or generation of samples. Experiments demonstrate the potential of the framework through qualitative and quantitative evaluation of the generated samples.', 13, 'ACCEPTED', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(5, 2, 'Deep Residual Learning for Image Recognition', 'Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper than those used previously. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs, instead of learning unreferenced functions. We provide comprehensive empirical evidence showing that these residual networks are easier to optimize, and can gain accuracy from considerably increased depth. On the ImageNet dataset we evaluate residual nets with a depth of up to 152 layers---8x deeper than VGG nets but still having lower complexity. An ensemble of these residual nets achieves 3.57% error on the ImageNet test set. This result won the 1st place on the ILSVRC 2015 classification task. We also present analysis on CIFAR-10 with 100 and 1000 layers. The depth of representations is of central importance for many visual recognition tasks. Solely due to our extremely deep representations, we obtain a 28% relative improvement on the COCO object detection dataset. Deep residual nets are foundations of our submissions to ILSVRC & COCO 2015 competitions, where we also won the 1st places on the tasks of ImageNet detection, ImageNet localization, COCO detection, and COCO segmentation.', 15, 'SUBMITTED', TRUE, NULL, '2026-01-07 04:29:04.768495'),
(6, 3, 'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding', 'We introduce a new language representation model called BERT, which stands for Bidirectional Encoder Representations from Transformers. Unlike recent language representation models, BERT is designed to pre-train deep bidirectional representations from unlabeled text by jointly conditioning on both left and right context in all layers. As a result, the pre-trained BERT model can be fine-tuned with just one additional output layer to create state-of-the-art models for a wide range of tasks, such as question answering and language inference, without substantial task-specific architecture modifications. BERT is conceptually simple and empirically powerful. It obtains new state-of-the-art results on eleven natural language processing tasks, including pushing the GLUE score to 80.5% (7.7% point absolute improvement), MultiNLI accuracy to 86.7% (4.6% absolute improvement), SQuAD v1.1 question answering Test F1 to 93.2 (1.5 point absolute improvement) and SQuAD v2.0 Test F1 to 83.1 (5.1 point absolute improvement).', 2, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(7, 5, 'Adam: A Method for Stochastic Optimization', 'We introduce Adam, an algorithm for first-order gradient-based optimization of stochastic objective functions, based on adaptive estimates of lower-order moments. The method is straightforward to implement, is computationally efficient, has little memory requirements, is invariant to diagonal rescaling of the gradients, and is well suited for problems that are large in terms of data and/or parameters. The method is also appropriate for non-stationary objectives and problems with very noisy and/or sparse gradients. The hyper-parameters have intuitive interpretations and typically require little tuning. Some connections to related algorithms, on which Adam was inspired, are discussed. We also analyze the theoretical convergence properties of the algorithm and provide a regret bound on the convergence rate that is comparable to the best known results under the online convex optimization framework. Empirical results demonstrate that Adam works well in practice and compares favorably to other stochastic optimization methods. Finally, we discuss AdaMax, a variant of Adam based on the infinity norm.', 3, 'ACCEPTED', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(8, 6, 'YOLOv3: An Incremental Improvement', 'We present some updates to YOLO! We made a bunch of little design changes to make it better. We also trained this new network that''s pretty swell. It''s a little bigger than last time but more accurate. It''s still fast though, don''t worry. At 320x320 YOLOv3 runs in 22 ms at 28.2 mAP, as accurate as SSD but three times faster. When we look at the old .5 IOU mAP detection metric YOLOv3 is quite good. It achieves 57.9 mAP@50 in 51 ms on a Titan X, compared to 57.5 mAP@50 in 198 ms by RetinaNet, similar performance but 3.8x faster.', 14, 'REVISION_REQ', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(9, 2, 'Language Models are Few-Shot Learners', 'Recent work has demonstrated substantial gains on many NLP tasks and benchmarks by pre-training on a large corpus of text followed by fine-tuning on a specific task. While typically task-agnostic in architecture, this method still requires task-specific fine-tuning datasets of thousands or tens of thousands of examples. By contrast, humans can generally perform a new language task from only a few examples or from simple instructions - something which current NLP systems still largely struggle to do. Here we show that scaling up language models greatly improves task-agnostic, few-shot performance, sometimes even reaching competitiveness with prior state-of-the-art fine-tuning approaches. Specifically, we train GPT-3, an autoregressive language model with 175 billion parameters, 10x more than any previous non-sparse language model, and test its performance in the few-shot setting. For all tasks, GPT-3 is applied without any gradient updates or fine-tuning, with tasks and few-shot demonstrations specified purely via text interaction with the model. GPT-3 achieves strong performance on many NLP datasets, including translation, question-answering, and cloze tasks, as well as several tasks that require on-the-fly reasoning or domain adaptation, such as unscrambling words, using a novel word in a sentence, or performing 3-digit arithmetic. At the same time, we also identify some datasets where GPT-3''s few-shot learning still struggles, as well as some datasets where GPT-3 faces methodological issues related to training on large web corpora. Finally, we find that GPT-3 can generate samples of news articles which human evaluators have difficulty distinguishing from articles written by humans. We discuss broader societal impacts of this finding and of GPT-3 in general.', 13, 'SUBMITTED', TRUE, NULL, '2026-01-07 04:29:04.768495'),
(10, 8, 'Mastering the game of Go with deep neural networks and tree search', 'The game of Go has long been viewed as the most challenging of classic games for artificial intelligence.', 15, 'ACCEPTED', TRUE, NULL, '2026-01-07 04:29:04.768495'),
(11, 3, 'XGBoost: A Scalable Tree Boosting System', 'Tree boosting is a highly effective and widely used machine learning method. In this paper, we describe a scalable end-to-end tree boosting system called XGBoost, which is used widely by data scientists to achieve state-of-the-art results on many machine learning challenges. We propose a novel sparsity-aware algorithm for sparse data and weighted quantile sketch for approximate tree learning. More importantly, we provide insights on cache access patterns, data compression and sharding to build a scalable tree boosting system. By combining these insights, XGBoost scales beyond billions of examples using far fewer resources than existing systems.', 14, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(12, 1, 'EfficientNet: Rethinking Model Scaling for Convolutional Neural Networks', 'Convolutional Neural Networks (ConvNets) are commonly developed at a fixed resource budget, and then scaled up for better accuracy if more resources are available. In this paper, we systematically study model scaling and identify that carefully balancing network depth, width, and resolution can lead to better performance. Based on this observation, we propose a new scaling method that uniformly scales all dimensions of depth/width/resolution using a simple yet highly effective compound coefficient. We demonstrate the effectiveness of this method on scaling up MobileNets and ResNet. To go even further, we use neural architecture search to design a new baseline network and scale it up to obtain a family of models, called EfficientNets, which achieve much better accuracy and efficiency than previous ConvNets. In particular, our EfficientNet-B7 achieves state-of-the-art 84.3% top-1 accuracy on ImageNet, while being 8.4x smaller and 6.1x faster on inference than the best existing ConvNet. Our EfficientNets also transfer well and achieve state-of-the-art accuracy on CIFAR-100 (91.7%), Flowers (98.8%), and 3 other transfer learning datasets, with an order of magnitude fewer parameters.', 14, 'REJECTED', FALSE, NULL, '2026-01-07 04:29:04.768495'),
(13, 1, 'Scalable Vision Transformers with Hierarchical Attention', 'The recently proposed Visual image Transformers (ViT) with pure attention have achieved promising performance on image recognition tasks, such as image classification. However, the routine of the current ViT model is to maintain a full-length patch sequence during inference, which is redundant and lacks hierarchical representation. To this end, we propose a Hierarchical Visual Transformer (HVT) which progressively pools visual tokens to shrink the sequence length and hence reduces the computational cost, analogous to the feature maps downsampling in Convolutional Neural Networks (CNNs). It brings a great benefit that we can increase the model capacity by scaling dimensions of depth/width/resolution/patch size without introducing extra computational complexity due to the reduced sequence length. Moreover, we empirically find that the average pooled visual tokens contain more discriminative information than the single class token. To demonstrate the improved scalability of our HVT, we conduct extensive experiments on the image classification task. With comparable FLOPs, our HVT outperforms the competitive baselines on ImageNet and CIFAR-100 datasets', 3, 'ACCEPTED', TRUE, NULL, '2026-01-07 06:10:50.633871'),
(14, 1, 'Denoising Diffusion Probabilistic Models for Image Synthesis', 'We present high quality image synthesis results using diffusion probabilistic models, a class of latent variable models inspired by considerations from nonequilibrium thermodynamics. Our best results are obtained by training on a weighted variational bound designed according to a novel connection between diffusion probabilistic models and denoising score matching with Langevin dynamics, and our models naturally admit a progressive lossy decompression scheme that can be interpreted as a generalization of autoregressive decoding. On the unconditional CIFAR10 dataset, we obtain an Inception score of 9.46 and a state-of-the-art FID score of 3.17. On 256x256 LSUN, we obtain sample quality similar to ProgressiveGAN. Our implementation is available at', 13, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(15, 2, 'A Survey on the Applications of Zero-Knowledge Proofs', 'Zero-knowledge proofs (ZKPs) represent a revolutionary advance in computational integrity and privacy technology, enabling the secure and private exchange of information without revealing underlying private data. ZKPs have unique advantages in terms of universality and minimal security assumptions when compared to other privacy-sensitive computational methods for distributed systems, such as homomorphic encryption and secure multiparty computation. Their application spans multiple domains, from enhancing privacy in blockchain to facilitating confidential verification of computational tasks. This survey starts with a high-level overview of the technical workings of ZKPs with a focus on an increasingly relevant subset of ZKPs called zk-SNARKS. While there have been prior surveys on the algorithmic and theoretical aspects of ZKPs, our work is distinguished by providing a broader view of practical aspects and describing many recently-developed use cases of ZKPs across various domains. These application domains span blockchain privacy, scaling, storage, and interoperability, as well as non-blockchain applications like voting, authentication, timelocks, and machine learning. Aimed at both practitioners and researchers, the survey also covers foundational components and infrastructure such as zero-knowledge virtual machines (zkVM), domain-specific languages (DSLs), supporting libraries, frameworks, and protocols. We conclude with a discussion on future directions, positioning ZKPs as pivotal in the advancement of cryptographic practices and digital privacy across many applications.', 17, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(16, 2, 'Web 3.0: The Future of Internet', 'With the rapid growth of the Internet, human daily life has become deeply bound to the Internet. To take advantage of massive amounts of data and information on the internet, the Web architecture is continuously being reinvented and upgraded. From the static informative characteristics of Web 1.0 to the dynamic interactive features of Web 2.0, scholars and engineers have worked hard to make the internet world more open, inclusive, and equal. Indeed, the next generation of Web evolution (i.e., Web 3.0) is already coming and shaping our lives. Web 3.0 is a decentralized Web architecture that is more intelligent and safer than before. The risks and ruin posed by monopolists or criminals will be greatly reduced by a complete reconstruction of the Internet and IT infrastructure. In a word, Web 3.0 is capable of addressing web data ownership according to distributed technology. It will optimize the internet world from the perspectives of economy, culture, and technology. Then it promotes novel content production methods, organizational structures, and economic forms. However, Web 3.0 is not mature and is now being disputed. Herein, this paper presents a comprehensive survey of Web 3.0, with a focus on current technologies, challenges, opportunities, and outlook. This article first introduces a brief overview of the history of World Wide Web as well as several differences among Web 1.0, Web 2.0, Web 3.0, and Web3. Then, some technical implementations of Web 3.0 are illustrated in detail. We discuss the revolution and benefits that Web 3.0 brings. Finally, we explore several challenges and issues in this promising area.', 20, 'SUBMITTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(17, 3, 'Autonomous UAV Navigation Using Reinforcement Learning', 'Unmanned aerial vehicles (UAV) are commonly used for missions in unknown environments, where an exact mathematical model of the environment may not be available. This paper provides a framework for using reinforcement learning to allow the UAV to navigate successfully in such environments. We conducted our simulation and real implementation to show how the UAVs can successfully learn to navigate through an unknown environment. Technical aspects regarding to applying reinforcement learning algorithm to a UAV system and UAV flight control were also addressed. This will enable continuing research using a UAV with learning capabilities in more important applications, such as wildfire monitoring, or search and rescue missions.', 18, 'ACCEPTED', TRUE, NULL, '2026-01-07 06:10:50.633871'),
(18, 3, 'Bioinspired Soft Robotics: state of the art, challenges, and future directions', 'Purpose of Review: This review provides an overview of the state of the art in bioinspired soft robotics with by examining advancements in actuation, functionality, modeling, and control. Recent Findings: Recent research into actuation methods, such as artificial muscles, have expanded the functionality and potential use of bioinspired soft robots. Additionally, the application of finite dimensional models has improved computational efficiency for modeling soft continuum systems, and garnered interest as a basis for controller formulation. Summary: Bioinspiration in the field of soft robotics has led to diverse approaches to problems in a range of task spaces. In particular, new capabilities in system simplification, miniaturization, and untethering have each contributed to the field’s growth. There is still significant room for improvement in the streamlining of design and manufacturing for these systems, as well as in their control.', 20, 'REVISION_REQ', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(19, 4, 'Gemini: A Family of Highly Capable Multimodal Models', 'This report introduces a new family of multimodal models, Gemini, that exhibit remarkable capabilities across image, audio, video, and text understanding. The Gemini family consists of Ultra, Pro, and Nano sizes, suitable for applications ranging from complex reasoning tasks to on-device memory-constrained use-cases. Evaluation on a broad range of benchmarks shows that our most-capable Gemini Ultra model advances the state of the art in 30 of 32 of these benchmarks - notably being the first model to achieve human-expert performance on the well-studied exam benchmark MMLU, and improving the state of the art in every one of the 20 multimodal benchmarks we examined. We believe that the new capabilities of the Gemini family in cross-modal reasoning and language understanding will enable a wide variety of use cases. We discuss our approach toward post-training and deploying Gemini models responsibly to users through services including Gemini, Gemini Advanced, Google AI Studio, and Cloud Vertex AI.', 15, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(20, 5, 'The current scope and stand of carbon capture storage and utilization', 'Over here in this paper, we have tried to present detailed information to the best of our knowledge regarding carbon capture storage and its utilization. CCU as well as CCS may be imagined with corresponding parts inside a coordinated framework that could move towards zero discharges that may be required for environment adjustment in the near times. Carbon Capture Storage may be considered as the wide-range extraction of CO2 from various important resources, it is then allowed and made ready for long-term isolation from the atmosphere and, then followed by its appropriate use. Our objective for this paper was to incorporate many technologies in these fields from the research and developmental activities which were a part of many articles and papers till date to the commercial uses and the challenges which are faced in this field and future scopes in this area. The sole purpose of the paper is to present the information in this domain available via different sources in one single paper which would help researchers a lot during their future references or research. Still, there are many kinds of research going on in this field that could be enhanced and paced up by such informative papers where all the required information is stored in a single paper. For the past twenty years, the oil industry and several scientific institutions have given importance to the concept of carbon capture and storage (CCS). A feasible method for storing carbon must be economical, environmentally friendly, and sustainable over the long term. As a result, carbon capture, utilization, and storage (CCUS) has emerged from CCS. The development of CCUS technology goes beyond the narrow focus on storage as it expanded to use carbon dioxide in oil extraction, treat alkaline industrial waste, and conversion of CO2 into useful chemicals to make this greenhouse gas economically viable. Fossil fuels will continue to be a significant source of energy in the following decades despite worldwide commitments to limit CO2 emissions. By converting high-emission industries to low-emission ones, CCUS contributes to the development of the low-emission economy of the future. Therefore, to improve our understanding of the long-term implications of developing alternative options such as large-scale CO2 injection into geological formations, carbon mineralization, and conversion of CO2 to synthesis, state-of-the-art research on carbon storage and utilization is required, and further analysis to understand the risks of CCUS from a technical, legislative, and political perspective. For individuals up for the challenge, CCUS research offers a chance to tackle technological issues that result in innovations with substantial economic and political implications for the oil and petrol sector.', 15, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(21, 6, 'Zero-Trust Architecture for Remote Work Security', 'secures remote work by abandoning the "trust but verify" model for "never trust, always verify," meaning every user, device, and connection is continuously authenticated and authorized, regardless of location. Key components include strict identity verification (MFA), least-privilege access, device health checks, micro-segmentation, and continuous monitoring to protect data in decentralized environments, replacing outdated VPN/perimeter security. ZTA is ideal for remote work as it reduces the attack surface and prevents lateral movement, securing access from anywhere, anytime.', 3, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(22, 6, 'A Multimodal Framework for DeepFake Detection', 'The rapid advancement of deepfake technology poses a significant threat to digital media integrity. Deepfakes, synthetic media created using AI, can convincingly alter videos and audio to misrepresent reality. This creates risks of misinformation, fraud, and severe implications for personal privacy and security. Our research addresses the critical issue of deepfakes through an innovative multimodal approach, targeting both visual and auditory elements. This comprehensive strategy recognizes that human perception integrates multiple sensory inputs, particularly visual and auditory information, to form a complete understanding of media content. For visual analysis, a model that employs advanced feature extraction techniques was developed, extracting nine distinct facial characteristics and then applying various machine learning and deep learning models. For auditory analysis, our model leverages mel-spectrogram analysis for feature extraction and then applies various machine learning and deep learning models. To achieve a combined analysis, real and deepfake audio in the original dataset were swapped for testing purposes and ensured balanced samples. Using our proposed models for video and audio classification i.e. Artificial Neural Network and VGG19, the overall sample is classified as deepfake if either component is identified as such. Our multimodal framework combines visual and auditory analyses, yielding an accuracy of 94%.', 20, 'SUBMITTED', TRUE, NULL, '2026-01-07 06:10:50.633871'),
(23, 7, 'Machine Learning and AI in Cancer Prognosis, Prediction, and Treatment Selection', 'Cancer is a leading cause of morbidity and mortality worldwide. While progress has been made in the diagnosis, prognosis, and treatment of cancer patients, individualized and data-driven care remains a challenge. Artificial intelligence (AI), which is used to predict and automate many cancers, has emerged as a promising option for improving healthcare accuracy and patient outcomes. AI applications in oncology include risk assessment, early diagnosis, patient prognosis estimation, and treatment selection based on deep knowledge. Machine learning (ML), a subset of AI that enables computers to learn from training data, has been highly effective at predicting various types of cancer, including breast, brain, lung, liver, and prostate cancer. In fact, AI and ML have demonstrated greater accuracy in predicting cancer than clinicians. These technologies also have the potential to improve the diagnosis, prognosis, and quality of life of patients with various illnesses, not just cancer. Therefore, it is important to improve current AI and ML technologies and to develop new programs to benefit patients. This article examines the use of AI and ML algorithms in cancer prediction, including their current applications, limitations, and future prospects.', 14, 'ACCEPTED', TRUE, NULL, '2026-01-07 06:10:50.633871'),
(24, 8, 'SoK: Stablecoin Designs, Risks, and the Stablecoin LEGO', 'Stablecoins have become significant assets in modern finance, with a market capitalization exceeding USD 246 billion (May 2025). Yet, despite their systemic importance, a comprehensive and risk-oriented understanding of crucial aspects like their design trade-offs, security dynamics, and interdependent failure pathways often remains underdeveloped. This SoK confronts this gap through a large-scale analysis of 157 research studies, 95 active stablecoins, and 44 major security incidents. Our analysis establishes four pivotal insights: 1) stability is best understood not an inherent property but an emergent, fragile state reliant on the interplay between market confidence and continuous liquidity; 2) stablecoin designs demonstrate trade-offs in risk specialization instead of mitigation; 3) the widespread integration of yield mechanisms imposes a “dual mandate” that creates a systemic tension between the core mission of stability and the high-risk financial engineering required for competitive returns; and 4) major security incidents act as acute “evolutionary pressures”, forging resilience by stress-testing designs and aggressively redefining the security frontier. We introduce the Stablecoin LEGO framework, a quantitative methodology mapping historical failures to current designs. Its application reveals that a lower assessed risk strongly correlates with integrating lessons from past incidents. We hope this provides a systematic foundation for building, evaluating, and regulating more resilient stablecoins.', 16, 'REJECTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(25, 1, 'Human-Level Reasoning: A Comparative Study of LLMs', 'Evaluating reasoning ability in Large Language Models (LLMs) is important for advancing artificial intelligence, as it transcends mere linguistic task performance. It involves understanding whether these models truly understand information, perform inferences, and are able to draw conclusions in a logical and valid way. This study compare logical and abstract reasoning skills of several LLMs - including GPT, Claude, DeepSeek, Gemini, Grok, Llama, Mistral, Perplexity, and Sabiá - using a set of eight custom-designed reasoning questions. The LLM results are benchmarked against human performance on the same tasks, revealing significant differences and indicating areas where LLMs struggle with deduction.', 2, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(26, 2, 'Edge Computing for Real-time Video Analytics', 'This paper proposes a novel edge computing enabled real-time video analysis system for intelligent visual devices. The proposed system consists of a tracking-assisted object detection module (TAODM) and a region of interesting module (ROIM). TAODM adaptively determines the offloading decision to process each video frame locally with a tracking algorithm or to offload it to the edge server inferred by an object detection model. ROIM determines each offloading frame''s resolution and detection model configuration to ensure that the analysis results can return in time. TAODM and ROIM interact jointly to filter the repetitive spatial-temporal semantic information to maximize the processing rate while ensuring high video analysis accuracy. Unlike most existing works, this paper investigates the real-time video analysis systems where the intelligent visual device connects to the edge server through a wireless network with fluctuating network conditions. We decompose the real-time video analysis problem into the offloading decision and configurations selection sub-problems. To solve these two sub-problems, we introduce a double deep Q network (DDQN) based offloading approach and a contextual multi-armed bandit (CMAB) based adaptive configurations selection approach, respectively. A DDQN-CMAB reinforcement learning (DCRL) training framework is further developed to integrate these two approaches to improve the overall video analyzing performance. Extensive simulations are conducted to evaluate the performance of the proposed solution, and demonstrate its superiority over counterparts.', 13, 'UNDER_REVIEW', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(27, 3, 'Human–Robot Collaborations in Smart Manufacturing Environments', 'The successful implementation of Human–Robot Collaboration (HRC) has become a prominent feature of smart manufacturing environments. Key industrial requirements, such as flexibility, efficiency, collaboration, consistency, and sustainability, present pressing HRC needs in the manufacturing sector. This paper provides a systemic review and an in-depth discussion of the key technologies currently being employed in smart manufacturing with HRC systems. The work presented here focuses on the design of HRC systems, with particular attention given to the various levels of Human–Robot Interaction (HRI) observed in the industry. The paper also examines the key technologies being implemented in smart manufacturing, including Artificial Intelligence (AI), Collaborative Robots (Cobots), Augmented Reality (AR), and Digital Twin (DT), and discusses their applications in HRC systems. The benefits and practical instances of deploying these technologies are showcased, emphasizing the substantial prospects for growth and improvement in sectors such as automotive and food. However, the paper also addresses the limitations of HRC utilization and implementation and provides some insights into how the design of these systems should be approached in future work and research. Overall, this paper provides new insights into the current state of HRC in smart manufacturing and serves as a useful resource for those interested in the ongoing development of HRC systems in the industry.', 17, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(28, 5, 'Optimizing Energy Distribution in Smart Grids with DRL', 'The rapid integration of renewable energy sources and the growing complexity of modern power systems have driven the need for efficient energy distribution mechanisms in smart grids. Deep Reinforcement Learning (DRL) has emerged as a promising approach to address these challenges by enabling intelligent decision-making and dynamic resource allocation. This paper explores the application of DRL techniques to optimize energy distribution in smart grids, focusing on key challenges such as demand-response management, grid stability, and renewable energy integration. We investigate state-of-the-art DRL algorithms, including Deep Q-Networks (DQN), Proximal Policy Optimization (PPO), and Soft Actor-Critic (SAC), to develop adaptive control strategies that balance supply and demand while minimizing energy losses and operational costs. A simulation-based framework is employed to model smart grid environments, incorporating stochastic energy generation, varying consumption patterns, and real-time pricing mechanisms. The results demonstrate that DRL-based controllers outperform traditional optimization methods by achieving higher efficiency, scalability, and adaptability to dynamic grid conditions. This research highlights the potential of DRL to revolutionize energy management in smart grids, paving the way for more resilient and sustainable power systems. Future work will explore the integration of multi-agent DRL approaches, enhanced security measures, and real-world deployment challenges.', 13, 'SUBMITTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(29, 6, 'The Post-Quantum Cryptography Transition', 'The development of quantum computing threatens the security of our currently widely deployed cryptographic algorithms. While signicant progress has been made in developing post-quantum cryptography (PQC) standards to protect against future quantum computing threats, the U.S. government''s estimated $7.1 billion transition cost for non-National Security Systems alone, coupled with an aggressive 2035 deadline, will require sustained funding, research, and international coordination to successfully upgrade existing cryptographic systems.', 13, 'REVISION_REQ', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(30, 7, 'AI in Genomics: Personalized Medicine', 'Personalized medicine entails tailoring medical care to an individual''s unique genomic and molecular characteristics. AI holds significant promise in advancing the field of personalized medicine. The challenge lies in effectively analyzing vast amounts of data to create tailored treatment approaches. The incorporation of AI into personalized treatment will require healthcare infrastructure adjustments. Upon patients'' arrival, their personal data and clinical information (including images, electrophysiology findings, genetic data, blood pressure, medical notes, etc.) are gathered into the AI system with their consent. Subsequently, the AI system utilizes this patient-specific data to offer healthcare recommendations, aiding healthcare professionals in their clinical decision-making. Results and insights from these recommendations, whether accurate or not, are logged and fed back into the AI system to enhance its precision.', 18, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(31, 8, 'WHEN IP MEETS NFTs: INTELLECTUAL PROPERTY PROTECTION', 'The world has seen enormous disruption by new age technologies in every domain of today''s economy including the arena of art, music and entertainment. Furthermore, the impact of artificial intelligence and blockchain technology particularly the Non Fungible Tokens (NFTs) has overwhelmed scholars about their understanding of laws related to intellectual property. Advances in technology are expanding the scope of intellectual property beyond traditional patents, trademarks, designs, trade secrets, plant breeders'' rights, and more. Various issues related to intellectual property have taken centre stage in the world of NFTs and Blockchains. Intellectual property disputes over virtual goods and NFTs are on the rise, and countries across the world are endeavoring to address the issues related to the protection of virtual goods. This article analyses the nature and scope of protection granted to virtual goods and NFTs in major jurisdictions viz the US and China. Further, the article analyses if the provisions of Indian IP Laws particularly the Trademarks and Designs Acts are sufficient to grant protection to the virtual goods.', 19, 'SUBMITTED', FALSE, NULL, '2026-01-07 06:10:50.633871'),
(32, 4, 'Computer Science Education in the Age of Generative AI', 'Generative AI tools—–most notably large language models (LLMs) like ChatGPT and Codex—–are rapidly revolutionizing computer science education. These tools can generate, debug, and explain code, thereby transforming the landscape of programming instruction. This paper examines the profound opportunities that AI offers for enhancing computer science education in general, from coding assistance to fostering innovative pedagogical practices and streamlining assessments. At the same time, it highlights challenges including academic integrity concerns, the risk of over-reliance on AI, and difficulties in verifying originality. We discuss what computer science educators should teach in the AI era, how to best integrate these technologies into curricula, and the best practices for assessing student learning in an environment where AI can generate code, prototypes and user feedback. Finally, we propose a set of policy recommendations designed to harness the potential of generative AI while preserving the integrity and rigour of computer science education. Empirical data and emerging studies are used throughout to support our arguments.', 16, 'ACCEPTED', FALSE, NULL, '2026-01-07 06:10:50.633871');
