INSERT INTO Reviews (review_id, paper_id, reviewer_id, status, recommendation, score, comments, review_date) VALUES 
(1, 1, 3, 'COMPLETED', 'ACCEPT', 4.5, 'This paper presents a well-motivated and novel approach to the problem, offering clear theoretical insights and practical relevance. The proposed method is original and advances the current state of the art.', '2026-01-07 03:47:42.807835'),
(2, 2, 3, 'COMPLETED', 'REVISION', 3.0, NULL, '2026-01-07 03:47:42.807835'),
(3, 3, 17, 'COMPLETED', 'REVISION', 2.0, 'Some assumptions made by the authors are not clearly stated or justified. The limitations of the proposed approach should be discussed more explicitly.', '2026-01-07 07:18:39.087464'),
(4, 3, 18, 'COMPLETED', 'REJECT', 1.7, 'The paper does not adequately compare against relevant state-of-the-art methods. Some closely related works are either missing or insufficiently discussed.', '2026-01-07 07:18:39.087464'),
(5, 3, 19, 'COMPLETED', 'WEAK_ACCEPT', 3.7, 'The proposed approach is generally sound, though some design choices are not fully justified. Additional analysis would strengthen the methodological rigor.', '2026-01-07 07:18:39.087464'),
(6, 3, 20, 'COMPLETED', 'REJECT', 1.2, 'The reported results are inconsistent and, in some cases, difficult to interpret. Statistical significance is not reported, which weakens the credibility of the conclusions.', '2026-01-07 07:18:39.087464'),
(7, 3, 25, 'COMPLETED', 'REJECT', 0.1, 'The claims made in the paper are overstated and not fully supported by the presented evidence. The conclusions go beyond what the experimental results can justify.', '2026-01-07 07:18:39.087464'),
(8, 3, 26, 'COMPLETED', 'REJECT', 1.6, 'The paper does not demonstrate sufficient novelty. Most of the ideas and techniques appear to be incremental variations of existing work, without clear differentiation from prior literature.', '2026-01-07 07:18:39.087464'),
(9, 3, 27, 'COMPLETED', 'REVISION', 2.5, 'More implementation details and hyperparameter settings should be provided to ensure the results can be reproduced. This revision is essential for technical transparency.', '2026-01-07 07:18:39.087464'),
(10, 3, 28, 'COMPLETED', 'REJECT', 0.1, 'The experimental section is weak. The evaluation is limited in scope, uses too few baselines, and does not convincingly demonstrate the effectiveness of the proposed method.', '2026-01-07 07:18:39.087464'),
(11, 3, 29, 'COMPLETED', 'WEAK_ACCEPT', 3.7, 'The paper is mostly well-written and easy to follow, although certain sections would benefit from clearer explanations and better organization.', '2026-01-07 07:18:39.087464'),
(12, 3, 30, 'COMPLETED', 'WEAK_ACCEPT', 3.9, 'The paper addresses an interesting problem and offers some novel aspects; however, the contribution is relatively incremental. While not groundbreaking, the ideas are still potentially useful.', '2026-01-07 07:18:39.087464'),
(13, 30, 17, 'COMPLETED', 'ACCEPT', 4.6, 'The paper is well-written, logically structured, and easy to read. Figures and tables are clear and effectively support the main claims of the paper.', '2026-01-07 07:18:39.087464'),
(14, 30, 18, 'COMPLETED', 'WEAK_ACCEPT', 3.8, 'The related work section covers the main references, but a deeper discussion of recent state-of-the-art methods would provide better context.', '2026-01-07 07:18:39.087464'),
(15, 30, 19, 'COMPLETED', 'REJECT', 1.7, 'Important implementation details are missing, making it difficult to reproduce the results. Several components of the method are vaguely described.', '2026-01-07 07:18:39.087464'),
(16, 30, 20, 'COMPLETED', 'REVISION', 2.2, 'Some claims in the paper are too strong given the current level of evidence. A revision is required to align the conclusions with the presented results.', '2026-01-07 07:18:39.087464'),
(17, 30, 25, 'COMPLETED', 'REVISION', 2.5, 'While the proposed method is interesting, important methodological details are missing or insufficiently justified. The authors should revise the paper to strengthen the technical soundness.', '2026-01-07 07:18:39.087464'),
(18, 30, 26, 'COMPLETED', 'REVISION', 2.6, 'The paper addresses a relevant problem; however, several key aspects of the approach require clearer explanation. A revision is necessary to improve the overall clarity and understanding.', '2026-01-07 07:18:39.087464'),
(19, 30, 27, 'COMPLETED', 'REVISION', 2.5, 'The experimental section needs to be expanded. Additional baselines, datasets, and ablation studies are required to properly validate the proposed approach.', '2026-01-07 07:18:39.087464'),
